@Component("document-handler")
@ProcessingGroup("document-processing-group")
public class DocumentEventHandler {
	
	// core constructor
	DocumentEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateDocumentEvent
     */
    @EventHandler
    public void handle( CreateDocumentEvent event) {
        entityManager.persist(new Document(event.getDocumentId(), event.getFileName(), event.getUploadedDate(), event.getPolicy(), event.getClaim(), event.getApplication(), event.getCustomer(), event.getDocumentType()));
    }

    /*
     * @param	event UpdateDocumentEvent
     */
    @EventHandler
    public Document handle( UpdateDocumentEvent event) {
    	entityManager.merge(new Document(event.getDocumentId(), event.getFileName(), event.getUploadedDate(), event.getPolicy(), event.getClaim(), event.getApplication(), event.getCustomer(), event.getDocumentType()));
    }
    
    /*
     * @param	event DeleteDocumentEvent
     */
    @EventHandler
    public void on( DeleteDocumentEvent event) {
    	Document entity = new Document();
   
    	// ------------------------------------------
    	// apply the DocumentId
    	// ------------------------------------------
    	entity.setDocumentId( event.getDocumentId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final DocumentRepository documentEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(DocumentEventHandler.class.getName());

}
